export type UiTreeResult = {
	tree: Value,
};

export type UiViewContribution = {
	plugin: string,
	/**  The providers the same plugin contributes: what `ownThreads` means. */
	providers: ProviderId[],
} & UiViewInfo;

/**  A view a plugin draws from the fixed set of UI nodes. */
export type UiViewInfo = {
	id: string,
	title: string,
	placement: UiPlacement,
	scope: UiScope,
	/**  A page of the plugin's web bundle shown instead of UI nodes. */
	web?: string | null,
};

/**  The one usage dialect: cumulative session total plus the last request. */
export type UsageSnapshot = {
	total: TokenUsage,
	last: TokenUsage,
	model_context_window?: number | null,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

export type WaitedThread = {
	thread: Thread,
	state: ThreadState,
	/**  The text of the agent's latest message: usually the answer. */
	last_message?: string | null,
};

/** Every request method: its parameters and its result. */
export type Methods = {
	"daemon.status": { params: Empty; result: DaemonStatusResult },
	"thread.spawn": { params: ThreadSpawnParams; result: ThreadResult },
	"thread.send": { params: ThreadSendParams; result: ThreadSendResult },
	"thread.unqueue": { params: ThreadUnqueueParams; result: ThreadUnqueueResult },
	"thread.set_mode": { params: ThreadSetModeParams; result: ThreadResult },
	"thread.set_agent": { params: ThreadSetAgentParams; result: ThreadResult },
	"thread.set_project": { params: ThreadSetProjectParams; result: ThreadResult },
	"thread.set_parent": { params: ThreadSetParentParams; result: ThreadResult },
	"thread.rename": { params: ThreadRenameParams; result: ThreadResult },
	"project.list": { params: Empty; result: ProjectListResult },
	"project.create": { params: ProjectCreateParams; result: ProjectResult },
	"project.update": { params: ProjectUpdateParams; result: ProjectResult },
	"project.delete": { params: ProjectDeleteParams; result: Empty },
	"thread.stop": { params: ThreadStopParams; result: Empty },
	"thread.list": { params: ThreadListParams; result: ThreadListResult },
	"thread.watch": { params: ThreadWatchParams; result: ThreadListResult },
	"thread.get": { params: ThreadGetParams; result: ThreadResult },
	"thread.archive": { params: ThreadArchiveParams; result: ThreadResult },
	"thread.changes": { params: ThreadGetParams; result: ThreadChangesResult },
	"thread.diff": { params: ThreadGetParams; result: ThreadDiffResult },
	"thread.deliver": { params: ThreadDeliverParams; result: ThreadDeliverResult },
	"thread.isolate": { params: ThreadIsolateParams; result: ThreadResult },
	"thread.wait": { params: ThreadWaitParams; result: ThreadWaitResult },
	"thread.events": { params: ThreadEventsParams; result: ThreadEventsResult },
	"thread.unsubscribe": { params: ThreadUnsubscribeParams; result: Empty },
	"interaction.resolve": { params: InteractionResolveParams; result: Empty },
	"plugin.list": { params: Empty; result: PluginListResult },
	"provider.models": { params: ProviderModelsParams; result: ProviderModelsResult },
	"settings.get": { params: Empty; result: SettingsResult },
	"settings.set": { params: SettingsSetParams; result: SettingsResult },
	"command.list": { params: Empty; result: CommandListResult },
	"command.run": { params: CommandRunParams; result: CommandRunResult },
	"ui.contributions": { params: Empty; result: UiContributionsResult },
	"ui.render": { params: UiRenderParams; result: UiTreeResult },
	"ui.action": { params: UiActionParams; result: UiTreeResult },
	"ui.render_item": { params: UiRenderItemParams; result: UiTreeResult },
	"ui.asset": { params: UiAssetParams; result: UiAssetResult },
};

/** Notifications the daemon pushes, by method name. */
export type Notifications = {
	"thread.event": ThreadEventNotification,
	"thread.updated": ThreadUpdatedNotification,
	"projects.updated": ProjectsUpdatedNotification,
};
